package com.werewolf;
import com.fasterxml.jackson.databind.*;
import com.werewolf.conversation.ConversationService;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.http.MediaType;
import org.springframework.mock.web.MockMultipartFile;
import org.springframework.test.context.ActiveProfiles;
import org.springframework.test.web.servlet.MockMvc;
import org.springframework.test.web.servlet.request.MockMvcRequestBuilders;
import javax.imageio.ImageIO;
import java.awt.image.BufferedImage;
import java.io.ByteArrayOutputStream;
import java.nio.charset.StandardCharsets;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
@SpringBootTest(properties="jiujiu.media.directory=target/test-chat-media") @AutoConfigureMockMvc @ActiveProfiles("h2")
class ConversationIntegrationTest {
 @Autowired MockMvc mvc; @Autowired ObjectMapper json; @Autowired ConversationService service;
 record User(long id,String token){}
 JsonNode call(String method,String path,String token,Object body)throws Exception{var req=MockMvcRequestBuilders.request(org.springframework.http.HttpMethod.valueOf(method),path);if(token!=null)req.header("Authorization","Bearer "+token);if(body!=null)req.contentType(MediaType.APPLICATION_JSON).content(json.writeValueAsString(body));return json.readTree(mvc.perform(req).andReturn().getResponse().getContentAsString(StandardCharsets.UTF_8));}
 JsonNode ok(String method,String path,User u,Object b)throws Exception{var r=call(method,path,u.token(),b);assertEquals(0,r.path("code").asInt(),r.toString());return r.path("data");}
 User user()throws Exception{String name="cv"+Long.toUnsignedString(System.nanoTime(),36);var r=call("POST","/api/auth/register",null,Map.of("username",name,"nickname",name,"password","demo1234"));assertEquals(0,r.path("code").asInt());return new User(r.path("data").path("user").path("id").asLong(),r.path("data").path("token").asText());}
 void friend(User a,User b)throws Exception{long id=ok("POST","/api/friends/requests",a,Map.of("targetUserId",b.id())).path("id").asLong();ok("POST","/api/friends/requests/"+id+"/accept",b,null);}
 long direct(User a,User b)throws Exception{return ok("POST","/api/conversations/direct",a,Map.of("targetUserId",b.id())).path("id").asLong();}
 Map<String,Object> text(String key,String content){return Map.of("clientMessageId",key,"contentType","TEXT","content",content);}
 @Test void directRequiresFriendAndKeepsHistoryAfterRemoval()throws Exception{var a=user();var b=user();var outsider=user();assertEquals(1002,call("POST","/api/conversations/direct",a.token(),Map.of("targetUserId",b.id())).path("code").asInt());friend(a,b);long cid=direct(a,b);assertEquals(cid,direct(b,a));long id=ok("POST","/api/conversations/"+cid+"/messages",a,text("direct-0001","你好 👋")).path("id").asLong();assertEquals(1,ok("GET","/api/conversations/"+cid,b,null).path("unreadCount").asInt());assertEquals(0,ok("GET","/api/conversations/"+cid,a,null).path("unreadCount").asInt());assertEquals(1002,call("GET","/api/conversations/"+cid+"/messages",outsider.token(),null).path("code").asInt());ok("DELETE","/api/friends/"+b.id(),a,null);assertEquals(1,ok("GET","/api/conversations/"+cid+"/messages",b,null).path("items").size());assertEquals(1002,call("POST","/api/conversations/"+cid+"/messages",a.token(),text("direct-0002","已删除")).path("code").asInt());ok("POST","/api/conversations/"+cid+"/read",b,Map.of("messageId",id));assertEquals(0,ok("GET","/api/conversations/"+cid,b,null).path("unreadCount").asInt());}
 @Test void concurrentRetryIsOneMessageAndChangedPayloadIsRejected()throws Exception{var a=user();var b=user();friend(a,b);long cid=direct(a,b);var pool=java.util.concurrent.Executors.newFixedThreadPool(2);try{var start=new java.util.concurrent.CountDownLatch(1);var f=pool.submit(()->{start.await();return service.send(a.id(),cid,"retry-key001","TEXT","hello",null);});var g=pool.submit(()->{start.await();return service.send(a.id(),cid,"retry-key001","TEXT","hello",null);});start.countDown();assertEquals(f.get().id(),g.get().id());}finally{pool.shutdownNow();}assertEquals(1,ok("GET","/api/conversations/"+cid+"/messages",b,null).path("items").size());assertEquals(1000,call("POST","/api/conversations/"+cid+"/messages",a.token(),text("retry-key001","different")).path("code").asInt());}
 @Test void historyCursorHasNoOverlapAndReadCursorNeverMovesBackwards()throws Exception{var a=user();var b=user();friend(a,b);long cid=direct(a,b);long first=0,last=0;for(int i=0;i<35;i++){long id=service.send(a.id(),cid,"history-"+String.format("%04d",i),"TEXT","消息"+i,null).id();if(i==0)first=id;last=id;}var newest=ok("GET","/api/conversations/"+cid+"/messages?limit=30",b,null);assertEquals(30,newest.path("items").size());assertTrue(newest.path("hasMore").asBoolean());long cursor=newest.path("nextBeforeId").asLong();var old=ok("GET","/api/conversations/"+cid+"/messages?beforeId="+cursor,b,null);assertEquals(5,old.path("items").size());assertTrue(old.path("items").get(4).path("id").asLong()<cursor);assertFalse(old.path("hasMore").asBoolean());ok("POST","/api/conversations/"+cid+"/read",b,Map.of("messageId",last));ok("POST","/api/conversations/"+cid+"/read",b,Map.of("messageId",first));assertEquals(0,ok("GET","/api/conversations/"+cid,b,null).path("unreadCount").asInt());var group=ok("POST","/api/groups",a,Map.of("name","other"));assertEquals(1000,call("POST","/api/conversations/"+group.path("id").asLong()+"/read",a.token(),Map.of("messageId",last)).path("code").asInt());}
 @Test void groupOwnershipMembershipAndClosingAreEnforced()throws Exception{var a=user();var b=user();var c=user();var g=ok("POST","/api/groups",a,Map.of("name","夜游群"));long cid=g.path("id").asLong();String code=g.path("code").asText();assertEquals(1002,call("GET","/api/groups/"+cid+"/members",c.token(),null).path("code").asInt());ok("POST","/api/groups/join",b,Map.of("code",code.toLowerCase()));assertEquals(2,ok("POST","/api/groups/join",b,Map.of("code",code)).path("memberCount").asInt());assertEquals(1002,call("PUT","/api/groups/"+cid,b.token(),Map.of("name","steal")).path("code").asInt());ok("POST","/api/conversations/"+cid+"/messages",a,text("group-00001","欢迎"));ok("POST","/api/groups/"+cid+"/leave",a,null);assertEquals(b.id(),ok("GET","/api/conversations/"+cid,b,null).path("createdBy").asLong());assertEquals(1002,call("GET","/api/conversations/"+cid+"/messages",a.token(),null).path("code").asInt());ok("PUT","/api/groups/"+cid,b,Map.of("name","新群名"));ok("POST","/api/groups/join",a,Map.of("code",code));assertEquals(1,ok("GET","/api/conversations/"+cid+"/messages",a,null).path("items").size());ok("POST","/api/groups/"+cid+"/leave",a,null);ok("POST","/api/groups/"+cid+"/leave",b,null);assertEquals(1003,call("POST","/api/groups/join",c.token(),Map.of("code",code)).path("code").asInt());}
 @Test void invitationIsServerAuthoredAndRequiresExplicitJoin()throws Exception{var a=user();var b=user();friend(a,b);var g=ok("POST","/api/groups",a,Map.of("name","约局"));long cid=g.path("id").asLong();var card=ok("POST","/api/groups/"+cid+"/invite",a,Map.of("targetUserId",b.id(),"clientMessageId","invite-0001"));assertEquals("GROUP_INVITE",card.path("contentType").asText());assertEquals(g.path("code"),card.path("relatedCode"));assertEquals(1002,call("GET","/api/conversations/"+cid,b.token(),null).path("code").asInt());assertEquals(1000,call("POST","/api/conversations/"+card.path("conversationId").asLong()+"/messages",a.token(),Map.of("contentType","GROUP_INVITE","clientMessageId","forged-0001","content","fake")).path("code").asInt());ok("POST","/api/groups/join",b,Map.of("code",card.path("relatedCode").asText()));assertEquals(2,ok("GET","/api/groups/"+cid+"/members",b,null).size());}
 @Test void privateImagesRequireCurrentConversationMembership()throws Exception{var a=user();var b=user();var c=user();var g=ok("POST","/api/groups",a,Map.of("name","图片群"));long cid=g.path("id").asLong();ok("POST","/api/groups/join",b,Map.of("code",g.path("code").asText()));var out=new ByteArrayOutputStream();ImageIO.write(new BufferedImage(3,2,BufferedImage.TYPE_INT_RGB),"png",out);var upload=multipart("/api/media/images").file(new MockMultipartFile("file","test.png","image/png",out.toByteArray())).param("purpose","PRIVATE").header("Authorization","Bearer "+a.token());var result=json.readTree(mvc.perform(upload).andReturn().getResponse().getContentAsString());String id=result.path("data").path("id").asText();assertEquals(1002,call("GET","/api/media/"+id+"/content",b.token(),null).path("code").asInt());ok("POST","/api/conversations/"+cid+"/messages",a,Map.of("clientMessageId","image-00001","contentType","IMAGE","mediaId",id));mvc.perform(get("/api/media/"+id+"/content").header("Authorization","Bearer "+b.token())).andExpect(content().contentType(MediaType.IMAGE_PNG));assertEquals(1002,call("GET","/api/media/"+id+"/content",c.token(),null).path("code").asInt());assertEquals(1002,call("POST","/api/conversations/"+cid+"/messages",b.token(),Map.of("clientMessageId","image-00002","contentType","IMAGE","mediaId",id)).path("code").asInt());ok("POST","/api/groups/"+cid+"/leave",b,null);assertEquals(1002,call("GET","/api/media/"+id+"/content",b.token(),null).path("code").asInt());}
 @Test void unicodeLimitAndInvalidTypesAreValidated()throws Exception{var a=user();var g=ok("POST","/api/groups",a,Map.of("name","边界"));String path="/api/conversations/"+g.path("id").asLong()+"/messages";ok("POST",path,a,text("unicode-0001","😀".repeat(2000)));assertEquals(1000,call("POST",path,a.token(),text("unicode-0002","😀".repeat(2001))).path("code").asInt());assertEquals(1000,call("POST",path,a.token(),text("unicode-0003","  ")).path("code").asInt());assertEquals(1000,call("POST",path,a.token(),text("bad","hi")).path("code").asInt());assertEquals(1000,call("GET","/api/conversations/"+g.path("id").asLong()+"/messages?limit=999",a.token(),null).path("code").asInt());}
}
